#ga_trigger_rules_modal .ga-trigger-card{width:min(1040px,calc(100vw - 40px))!important;max-height:calc(100vh - 40px)!important;overflow:hidden!important;background:#fff!important;border:1px solid rgba(219,228,240,.95)!important;border-radius:18px!important;box-shadow:0 24px 64px rgba(15,23,42,.24)!important;padding:0!important;margin:0!important;}
#ga_trigger_rules_modal .modal-head{height:54px!important;padding:0 16px!important;margin:0!important;border-bottom:1px solid var(--crm-border)!important;display:flex!important;align-items:center!important;justify-content:space-between!important;gap:12px!important;}
