#ga_role_editor_card .ga-normalized-modal-body>.grid.ga-role-editor-single>div{background:#f8fbff!important;border:1px solid var(--crm-border)!important;border-radius:16px!important;padding:14px!important;min-width:0!important;width:100%!important;}
